 return `<div class="champ-active"><div class="row between wrap"><div><h3>🏁 ${t.name}</h3><div class="subtle">${t.laps} laps · your pace ${lapTime().toFixed(1)}s · rival pace ${c.rivalLap.toFixed(1)}s</div></div><span class="badge live">LIVE</span></div>
 <div class="champ-bars"><div class="champ-bar-row player"><span>YOU</span><div class="bar"><i id="champPlayerBar" style="width:${pp}%"></i></div><span id="champLapText">${Math.min(t.laps,Math.floor(c.elapsed/Math.max(.1,lapTime())))}/${t.laps}</span></div>
 <div class="champ-bar-row rival"><span>RIVAL</span><div class="bar"><i id="champRivalBar" style="width:${rp}%"></i></div><span>${Math.min(t.laps,Math.floor(c.elapsed/Math.max(.1,c.rivalLap)))}/${t.laps}</span></div></div>
 <div class="row between wrap" style="margin-top:11px"><span class="subtle" id="champStatus">${c.won?'You have the pace to win — hold it.':'Rival is faster. Upgrade and try again.'}</span><button class="btn small danger" data-action="abandon">ABANDON</button></div></div>`;
}
function ladderCard(t,i){
 const st=tierStatus(i),active=state.champ&&state.champ.tier===i,canEnter=i<=state.unlockedTier&&!state.won.includes(i);
 return `<div class="ladder-card ${st[1]}"><div class="ladder-num">${String(i+1).padStart(2,'0')}</div><div class="ladder-body"><div class="row between"><h3>${t.name}</h3><span class="badge ${st[1]==='ready'?'ready':st[1]==='won'?'won':st[1]==='live'?'live':''}">${st[0]}</span></div><p>${t.laps} laps · rival ${t.rivalLap.toFixed(1)}s/lap · ${cash(t.reward)} · ${fmt(t.trophies)} ✦</p><div class="ladder-actions">${canEnter&&!active?`<button class="btn small" data-champ="${i}">ENTER RACE →</button>`:''}${active?'<span class="subtle">Race in progress — live progress is above.</span>':''}${state.won.includes(i)?'<span class="subtle">Championship cleared.</span>':''}${!canEnter&&!state.won.includes(i)&&!active?`<span class="subtle">Win ${i>0?TIERS[i-1].name:'the previous cup'} to unlock.</span>`:''}</div></div></div>`;
}
function champPulseHTML(){
 if(state.champ)return activeChampHTML();
 const next=TIERS.findIndex((t,i)=>!state.won.includes(i)&&i<=state.unlockedTier);
 if(next<0)return `<div class="panel"><div class="panel-head"><div><h2>Championship pulse</h2><p>Every ladder rung is cleared. You are the Apex champion.</p></div><span class="tag">APEX</span></div></div>`;
 const t=TIERS[next];
 return `<div class="panel"><div class="panel-head"><div><h2>Championship pulse</h2><p>Next up: ${t.name}. Beat a ${t.rivalLap.toFixed(1)}s rival lap over ${t.laps} laps.</p></div><span class="tag">NEXT</span></div><div class="row between wrap"><div><b style="font-size:11px">${t.name}</b><div class="subtle" style="margin-top:4px">${cash(t.reward)} and ${fmt(t.trophies)} trophies · bonus card on victory</div></div><button class="btn" data-champ="${next}">ENTER RACE →</button></div><div class="subtle" style="margin-top:9px">Your current pace is ${lapTime().toFixed(1)}s/lap. ${lapTime()<=t.rivalLap?'You are quicker than the rival.':'The rival is quicker — add upgrades first.'}</div></div>`;
}
function viewRace(){
 const world=WORLDS[state.world]||WORLDS[0];
 return `<div class="panel"><div class="panel-head"><div><h2>Track session</h2><p>Your crew keeps lapping and earning while you watch or idle.</p></div><span class="tag">AFK ON</span></div>
 <div class="session-grid"><div class="session-world"><div class="big-emoji">${world.emoji}</div><div><b>${world.name}</b><p>${world.desc}</p></div></div><div class="session-metrics"><div><span>Payout</span><b class="mint">×${worldMult().toFixed(2)}</b></div><div><span>Per sec</span><b>${cash(perSecond())}</b></div><div><span>Next lap</span><b id="raceNextLap">${lapTime().toFixed(1)}s</b></div></div></div>
 <div class="row wrap"><button class="btn secondary" data-tab="worlds">Change world →</button><button class="btn secondary" data-tab="champ">Championships →</button><button class="btn secondary" data-tab="garage">Garage →</button></div></div>
 ${champPulseHTML()}
 <div class="panel"><div class="panel-head"><div><h2>Pit crew prestige</h2><p>Reset the ladder and upgrades for permanent Golden Wrenches.</p></div><span class="tag">${state.prestige} 🔧</span></div><div class="row between wrap"><div><b style="font-size:11px">Permanent bonus</b><div class="subtle" style="margin-top:4px">+${state.prestige*20}% cash · +${state.prestige*3}% pack luck · cars, worlds and skins are kept</div></div><button class="btn goldbtn" data-action="prestige" ${state.unlockedTier<3?'disabled':''}>${state.unlockedTier<3?'UNLOCK ELITE TO PRESTIGE':'PRESTIGE'}</button></div></div>
 <div class="panel"><div class="panel-head"><div><h2>How the club works</h2><p>Three simple loops, always running.</p></div></div><div class="grid-3"><div><b style="font-size:10px">🏁 Race</b><p class="subtle" style="margin-top:4px;line-height:1.5">Laps pay cash and XP automatically. Trophies arrive every 5 laps.</p></div><div><b style="font-size:10px">🏆 Championship</b><p class="subtle" style="margin-top:4px;line-height:1.5">Beat the rival pace to unlock the next tier and a bonus card.</p></div><div><b style="font-size:10px">🎴 Collect</b><p class="subtle" style="margin-top:4px;line-height:1.5">Packs add cars. Three copies merge into a permanent star.</p></div></div></div>`;
}
function viewChamp(){
 return `<div class="panel"><div class="panel-head"><div><h2>Championship ladder</h2><p>Five tiers. Win each one to unlock the next, earn trophies, and claim a bonus card.</p></div><span class="tag">${state.won.length}/5 WON</span></div>${activeChampHTML()}<div class="ladder">${TIERS.map(ladderCard).join('')}</div></div>
 <div class="panel"><div class="panel-head"><div><h2>Pit crew prestige</h2><p>Reach Elite Tour, then reset for permanent Golden Wrenches.</p></div><span class="tag">${state.prestige} 🔧</span></div><div class="row between wrap"><div><b style="font-size:11px">+${state.prestige*20}% cash & +${state.prestige*3}% pack luck</b><div class="subtle" style="margin-top:4px">Resets cash, trophies, XP, upgrades and the ladder. Collection, worlds and skins stay.</div></div><button class="btn goldbtn" data-action="prestige" ${state.unlockedTier<3?'disabled':''}>${state.unlockedTier<3?'LOCKED':'PRESTIGE'}</button></div></div>`;
}
function viewUpgrades(){
 return `<div class="panel"><div class="panel-head"><div><h2>Performance upgrades</h2><p>Every level lowers lap time or raises payout. Buy in batches.</p></div><div class="row"><button class="btn small ${buyMode===1?'':'secondary'}" data-buy="1">×1</button><button class="btn small ${buyMode===10?'':'secondary'}" data-buy="10">×10</button></div></div><div class="upgrade-grid">${UPGRADES.map(u=>{const lv=state.upgrades[u.key],max=lv>=MAX_LEVEL,n=Math.min(buyMode,MAX_LEVEL-lv),cost=upgradeCost(u.key,Math.max(1,n));return `<article class="upgrade-card"><div class="row between"><div class="up-ico">${u.icon}</div><span class="badge">LV ${lv}/${MAX_LEVEL}</span></div><h3>${u.name}</h3><p>${u.desc}</p><div class="effect">${u.effect} per level</div><div class="row between" style="margin-top:10px"><span class="cost">${max?'MAXED':cash(cost)}</span><button class="btn small" data-upgrade="${u.key}" ${max?'disabled':''}>${max?'MAX':'BUY ×'+n}</button></div></article>`}).join('')}</div></div>
 <div class="panel"><div class="panel-head"><div><h2>Tuning summary</h2><p>Current build after upgrades, equipped car and stars.</p></div></div><div class="grid-4"><div><span class="subtle">Lap time</span><b style="display:block;font-size:15px;margin-top:4px">${lapTime().toFixed(1)}s</b></div><div><span class="subtle">Cash / lap</span><b class="mint" style="display:block;font-size:15px;margin-top:4px">${cash(cashPerLap())}</b></div><div><span class="subtle">Payout mult</span><b style="display:block;font-size:15px;margin-top:4px">×${payoutMult().toFixed(2)}</b></div><div><span class="subtle">Next tier pace</span><b style="display:block;font-size:15px;margin-top:4px">${TIERS[Math.min(state.unlockedTier,4)].rivalLap.toFixed(1)}s</b></div></div></div>`;
}
function viewPacks(){
 return `<div class="panel"><div class="panel-head"><div><h2>Card pack shop</h2><p>Cash or trophies. Every pull can add a new car or a merge copy.</p></div><span class="tag">${Object.keys(state.collection).length}/18 CARS</span></div><div class="pack-grid">${PACKS.map((p,i)=>{const od=packOdds(p),cols=['#55d8ac','#69bfff','#d86dff','#ffce67'];return `<article class="pack-card" style="--p1:${p.colors[0]};--p2:${p.colors[1]}"><div class="pack-top"><div class="pack-icon">${p.icon}</div><div><h3>${p.name}</h3><p>${p.blurb}</p></div></div><div class="odds">${od.map((v,k)=>`<i style="width:${v}%;background:${cols[k]}"></i>`).join('')}</div><div class="odds-legend">${['Common','Rare','Epic','Legendary'].map((r,k)=>`<span><b style="background:${cols[k]}"></b>${r} ${Math.round(od[k])}%</span>`).join('')}</div><div class="subtle">${p.cards} card${p.cards>1?'s':''} · duplicates merge</div><div class="pack-actions" style="margin-top:9px"><button class="btn small" data-pack="${i}" data-currency="cash">${cash(p.cash)}</button><button class="btn small goldbtn" data-pack="${i}" data-currency="trophy">${p.trophies} ✦</button></div></article>`}).join('')}</div></div>
 <div class="panel"><div class="panel-head"><div><h2>Collection progress</h2><p>Three copies of a car make one star. Five stars is the maximum.</p></div><span class="tag">${state.packsOpened} PACKS</span></div><div class="progress goldbar"><i style="width:${Object.keys(state.collection).length/18*100}%"></i></div><div class="row between" style="margin-top:9px"><span class="subtle">${Object.keys(state.collection).length} of 18 cars discovered</span><span class="subtle">+${state.prestige*3}% pack luck from wrenches</span></div></div>`;
}
function viewGarage(){
 const car=CARS[state.car]||CARS[0];
 return `<div class="panel"><div class="panel-head"><div><h2>Your garage</h2><p>Equip a car, collect copies, and merge three at a time into stars.</p></div><span class="tag">${Object.keys(state.collection).length}/18</span></div><div class="row between wrap" style="background:#0a1825;border:1px solid #1b3345;border-radius:11px;padding:11px;margin-bottom:12px"><div class="row"><div class="big-emoji">${car.emoji}</div><div><b style="font-size:11px">${car.name}</b><div class="subtle">${car.cls} · ${car.rarity} · ${'★'.repeat(carStars(state.car))}${'☆'.repeat(5-carStars(state.car))}</div></div></div><div class="row"><span class="subtle">SPD</span><b>${car.speed}</b><span class="subtle">PAY</span><b>${car.payout}</b></div></div><div class="garage-grid">${CARS.map((c,i)=>{const count=state.collection[i]||0,owned=count>0,stars=carStars(i),eq=state.car===i,next=count%3;return `<article class="car-card ${owned?'':'locked'} ${eq?'equipped':''}"><div class="star-row">${'★'.repeat(stars)}${'☆'.repeat(5-stars)}</div><div class="car-art">${c.emoji}</div><h3>${c.name}</h3><p>${c.cls}</p><div class="row between"><span class="rarity r-${c.rarity}">${c.rarity}</span><span class="subtle">×${count}</span></div><div class="mini-stats"><span>SPD <b>${c.speed}</b></span><span>PAY <b>${c.payout}</b></span></div>${owned?`<button class="btn small ${eq?'secondary':''}" data-equip="${i}" ${eq?'disabled':''}>${eq?'EQUIPPED':'EQUIP'}</button><div class="merge-note">${stars>=5?'MAX STARS':`${next}/3 to ★${stars+1}`}</div>`:'<button class="btn small secondary" disabled>LOCKED</button>'}</article>`}).join('')}</div></div>
 <div class="panel"><div class="panel-head"><div><h2>Paint & skin packs</h2><p>Each finish is rarer and more expensive. Owned paint applies to your car in every view.</p></div><span class="tag">${state.skins.length}/6</span></div><div class="skin-grid">${SKINS.map(s=>{const owned=state.skins.includes(s.id),active=state.skin===s.id;return `<article class="skin-card ${active?'active':''}"><div class="swatch" style="--sw:${s.color}"></div><div class="row between"><h4>${s.name}</h4><span class="rarity r-${s.rarity}">${s.rarity}</span></div><p>+${Math.round(s.bonus*100)}% payout</p><button class="btn small ${owned?'':'secondary'}" data-skin="${s.id}">${owned?(active?'APPLIED':'APPLY'):cash(s.price)}</button></article>`}).join('')}</div></div>`;
}
function viewWorlds(){
 return `<div class="panel"><div class="panel-head"><div><h2>World select</h2><p>Twenty-one roads. Unlock them with cash and each one pays more than the last.</p></div><span class="tag">${state.worlds.length}/21</span></div><div class="world-grid">${WORLDS.map((w,i)=>{const open=state.worlds.includes(i),active=state.world===i;return `<article class="world-card ${active?'active':''} ${open?'':'locked'}" style="--acc:${w.accent}"><div class="row between"><span class="world-emoji">${w.emoji}</span><span class="world-mult">×${worldMult(i).toFixed(2)}</span></div><h4>${w.name}</h4><p>${w.desc}</p><div class="world-foot"><span class="subtle">${active?'RACING':open?'UNLOCKED':'LOCKED'}</span><button class="btn small ${active?'secondary':''}" data-world="${i}" ${active?'disabled':''}>${open?(active?'ACTIVE':'SELECT'):cash(worldCost(i))}</button></div></article>`}).join('')}</div></div>`;
}
function viewForTab(){
 if(tab==='champ')return viewChamp();if(tab==='upgrades')return viewUpgrades();if(tab==='packs')return viewPacks();if(tab==='garage')return viewGarage();if(tab==='worlds')return viewWorlds();return viewRace();
}
function sidebarHTML(car,world){
 return `<aside class="sidecol"><section class="panel"><div class="side-title"><h3>Championship ladder</h3><span>${state.won.length}/5 WON</span></div><div class="side-ladder">${TIERS.map((t,i)=>{const st=tierStatus(i),ready=i<=state.unlockedTier&&!state.won.includes(i)&&!(state.champ&&state.champ.tier===i);return `<div class="side-tier ${st[1]==='ready'?'ready':st[1]==='won'?'won':''}"><span>${t.emoji||'🏁'} ${t.name}</span>${ready?`<button class="btn small" data-champ="${i}">GO</button>`:`<span class="subtle">${st[0]}</span>`}</div>`}).join('')}</div></section>
 <section class="panel"><div class="side-title"><h3>Race rewards</h3><span>LIVE</span></div><div class="side-row"><span class="muted">Cash / second</span><b class="mint" id="sidePerSec">${cash(perSecond())}</b></div><div class="side-row"><span class="muted">Cash / lap</span><b id="sidePerLap">${cash(cashPerLap())}</b></div><div class="side-row"><span class="muted">Next lap</span><b id="countdown">${lapTime().toFixed(1)}s</b></div><div class="progress"><i id="lapProgress" style="width:0%"></i></div></section>
 <section class="panel"><div class="side-title"><h3>Garage snapshot</h3><span>CAR ${String(state.car+1).padStart(2,'0')}</span></div><div class="side-row"><span>${car.emoji} ${car.name}</span><button class="btn secondary small" data-tab="garage">VIEW</button></div><div class="divider"></div><div class="side-row"><span class="muted">Collection</span><b>${Object.keys(state.collection).length}/18</b></div><div class="side-row"><span class="muted">Paint finishes</span><b>${state.skins.length}/6</b></div><div class="side-row"><span class="muted">Stars on current car</span><b class="gold">${carStars(state.car)} ★</b></div></section>
 <section class="panel"><div class="side-title"><h3>Active world</h3><span>PAYOUT ×${worldMult().toFixed(2)}</span></div><div class="side-row"><span>${world.emoji} ${world.name}</span><button class="btn secondary small" data-tab="worlds">MAP</button></div><div class="subtle" style="margin-top:8px;line-height:1.5">${world.desc}</div></section></aside>`;
}
function render(){
 const car=CARS[state.car]||CARS[0],world=WORLDS[state.world]||WORLDS[0],xpPct=clamp(state.xp/xpNeeded()*100,0,100);
 $('#app').innerHTML=`<div class="shell">${topbarHTML(car)}<div class="layout"><main class="maincol">${heroHTML(car,world)}${statsHTML(xpPct)}${tabsHTML()}<div id="tabContent">${viewForTab()}</div><div class="footer">Autosaves locally · Offline earnings accrue for up to 12 hours · ${state.totalEarned?cash(state.totalEarned)+' earned all-time':''}</div></main>${sidebarHTML(car,world)}</div></div>`;
 updateHud();
}
/* __UI__ */

