  g.fillStyle='rgba(220,245,255,.65)';g.font='800 9px Inter, sans-serif';g.textAlign='center';g.fillText('FULL TRACK VIEW',cx,h*.1);
 }
 function min(a,b){return Math.min(a,b)}
 /* __CANVAS__ */
+function topbarHTML(car){
+ return `<header class="topbar"><div class="brand"><div class="brandmark">◈</div><div>PITLANE<small>Idle Racing Club</small></div></div><div class="pills">
+ <div class="pill cash" title="Cash">◉ <span class="pill-label">Cash</span><b id="cashBalance">${cash(state.cash)}</b></div>
+ <div class="pill trophy" title="Trophies">✦ <span class="pill-label">Trophies</span><b id="trophyBalance">${fmt(state.trophies)}</b></div>
+ <div class="pill" title="Level">✧ <span class="pill-label">Level</span><b id="levelValue">${fmt(state.level)}</b></div>
+ ${state.prestige?`<div class="pill wrench" title="Golden wrenches">🔧 <span class="pill-label">Wrench</span><b id="wrenchBalance">${state.prestige}</b></div>`:''}
+ <button class="iconbtn ${state.sound?'on':''}" data-action="sound" aria-label="${state.sound?'Mute sound':'Enable sound'}" aria-pressed="${state.sound}">${state.sound?'♪':'✕'}</button>
+ <div class="profile" title="${car.name}">${car.emoji}</div>
+ </div></header>`;
+}
+function heroHTML(car,world){
+ return `<section class="hero"><canvas id="raceCanvas" aria-label="Animated ${world.name} race track"></canvas>
+ <div class="scene-top"><span class="live"><i></i> LIVE RACE</span><span class="track-chip">${world.emoji} ${world.name}</span></div>
+ <div class="scene-controls"><button data-action="camera" class="${state.follow?'on':''}" aria-pressed="${state.follow}">${state.follow?'◉ FOLLOW':'▧ FULL TRACK'}</button><button data-action="sound" class="${state.sound?'on':''}" aria-pressed="${state.sound}">${state.sound?'♫ SOUND':'♫ MUTED'}</button></div>
+ <div class="hero-champ" id="heroChamp"><span id="heroChampName"></span><b id="heroChampLap"></b></div>
+ <div class="race-bottom"><div class="race-title"><div class="eyebrow">${car.rarity} · ${car.cls}</div><h1>${car.emoji} ${car.name}</h1><p><b>${cash(perSecond())}</b>/sec <span>·</span> <b>${cash(cashPerLap())}</b>/lap <span>·</span> ${world.name}</p></div>
+ <div class="lapbox"><span>COMPLETED LAPS</span><b id="lapCount">${fmt(state.laps)}</b><div class="speed-row">${[1,2,4].map(v=>`<button data-speed="${v}" class="${state.speedMult===v?'on':''}" aria-pressed="${state.speedMult===v}">${v}×</button>`).join('')}</div></div></div></section>`;
+}
+function statsHTML(xpPct){
+ return `<div class="stats">
+ <div class="stat"><span class="label">Cash / lap</span><strong class="mint" id="statCashLap">${cash(cashPerLap())}</strong><small id="statPerSec">${cash(perSecond())}/sec</small></div>
+ <div class="stat"><span class="label">Lap time</span><strong id="statLap">${lapTime().toFixed(1)}s</strong><small>auto racing</small></div>
+ <div class="stat"><span class="label">Experience</span><strong><span id="xpValue">${fmt(state.xp)}</span> <small>/ <span id="xpNeed">${fmt(xpNeeded())}</span> XP</small></strong><div class="progress"><i id="xpFill" style="width:${xpPct}%"></i></div></div>
+ <div class="stat"><span class="label">Golden wrenches</span><strong class="gold" id="statWrench">${state.prestige} 🔧</strong><small>+${state.prestige*20}% cash · +${state.prestige*3}% pack luck</small></div>
+ </div>`;
+}
+function tabsHTML(){
+ return `<div class="tabs" role="tablist">${TABS.map(([key,label])=>`<button class="tab ${tab===key?'on':''}" data-tab="${key}" role="tab" aria-selected="${tab===key}">${label}</button>`).join('')}</div>`;
+}
+function tierStatus(i){
+ if(state.won.includes(i))return ['CLEARED','won'];
+ if(state.champ&&state.champ.tier===i)return ['RACING','live'];
+ if(i<=state.unlockedTier)return ['READY','ready'];
+ return ['LOCKED',''];
+}
+function activeChampHTML(){
+ const c=state.champ;if(!c)return '';
+ const t=TIERS[c.tier],pp=clamp(c.elapsed/c.playerTotal*100,0,100),rp=clamp(c.elapsed/c.rivalTotal*100,0,100);
+ return `<div class="champ-active"><div class="row between wrap"><div><h3>🏁 ${t.name}</h3><div class="subtle">${t.laps} laps · your pace ${lapTime().toFixed(1)}s · rival pace ${c.rivalLap.toFixed(1)}s</div></div><span class="badge live">LIVE</span></div>
+ <div class="champ-bars"><div class="champ-bar-row player"><span>YOU</span><div class="bar"><i id="champPlayerBar" style="width:${pp}%"></i></div><span id="champLapText">${Math.min(t.laps,Math.floor(c.elapsed/Math.max(.1,lapTime())))}/${t.laps}</span></div>
+ <div class="champ-bar-row rival"><span>RIVAL</span><div class="bar"><i id="champRivalBar" style="width:${rp}%"></i></div><span>${Math.min(t.laps,Math.floor(c.elapsed/Math.max(.1,c.rivalLap)))}/${t.laps}</span></div></div>
+ <div class="row between wrap" style="margin-top:11px"><span class="subtle" id="champStatus">${c.won?'You have the pace to win — hold it.':'Rival is faster. Upgrade and try again.'}</span><button class="btn small danger" data-action="abandon">ABANDON</button></div></div>`;
+}
+function ladderCard(t,i){
+ const st=tierStatus(i),active=state.champ&&state.champ.tier===i,canEnter=i<=state.unlockedTier&&!state.won.includes(i);
+ return `<div class="ladder-card ${st[1]}"><div class="ladder-num">${String(i+1).padStart(2,'0')}</div><div class="ladder-body"><div class="row between"><h3>${t.name}</h3><span class="badge ${st[1]==='ready'?'ready':st[1]==='won'?'won':st[1]==='live'?'live':''}">${st[0]}</span></div><p>${t.laps} laps · rival ${t.rivalLap.toFixed(1)}s/lap · ${cash(t.reward)} · ${fmt(t.trophies)} ✦</p><div class="ladder-actions">${canEnter&&!active?`<button class="btn small" data-champ="${i}">ENTER RACE →</button>`:''}${active?'<span class="subtle">Race in progress — live progress is above.</span>':''}${state.won.includes(i)?'<span class="subtle">Championship cleared.</span>':''}${!canEnter&&!state.won.includes(i)&&!active?`<span class="subtle">Win ${i>0?TIERS[i-1].name:'the previous cup'} to unlock.</span>`:''}</div></div></div>`;
+}
+function champPulseHTML(){
