function save(){state.last=Date.now();try{localStorage.setItem(SAVE_KEY,JSON.stringify(state))}catch{}}
function showToast(msg,kind=''){const el=$('#toast');if(!el)return;el.textContent=msg;el.className='toast show '+kind;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2600)}
function getAudio(){try{if(!audioCtx){const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return null;audioCtx=new AC()}if(audioCtx.state==='suspended')audioCtx.resume().catch(()=>{});return audioCtx}catch{return null}}
function tone(freq,delay,dur,type='sine',vol=.03,endFreq){const c=getAudio();if(!c)return;try{const o=c.createOscillator(),g=c.createGain(),t=c.currentTime+delay;o.type=type;o.frequency.setValueAtTime(freq,t);if(endFreq)o.frequency.exponentialRampToValueAtTime(endFreq,t+dur);g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(vol,t+.012);g.gain.exponentialRampToValueAtTime(.0001,t+dur);o.connect(g);g.connect(c.destination);o.start(t);o.stop(t+dur+.03)}catch{}}
function sound(name){if(!state.sound)return;try{if(name==='tap')tone(520,0,.07,'sine',.024);else if(name==='upgrade'){[440,660,880].forEach((f,i)=>tone(f,i*.06,.1,'triangle',.028))}else if(name==='pack'){[523,659,784,1047].forEach((f,i)=>tone(f,i*.075,.16,'sine',.026))}else if(name==='lap'){tone(880,0,.08,'sine',.02);tone(1174,.06,.11,'sine',.016)}else if(name==='win'){[523,659,784,1047].forEach((f,i)=>tone(f,i*.03,.55,'triangle',.032));tone(1568,.16,.35,'sine',.022)}else if(name==='error')tone(190,0,.16,'sawtooth',.02,130);else if(name==='merge'){tone(660,0,.09,'triangle',.028);tone(990,.08,.14,'triangle',.026)}else if(name==='buy'){tone(620,0,.05,'sine',.023);tone(930,.05,.08,'sine',.02)}}catch{}}
function addXp(n){state.xp+=Math.max(0,Number(n)||0);let gained=0;while(state.xp>=xpNeeded()&&gained<100){const need=xpNeeded();state.xp-=need;state.level++;gained++}if(gained){const bonus=gained*150;state.cash+=bonus;showToast(`LEVEL ${state.level} · +${cash(bonus)} bonus`,'gold');sound('win')}}
function offlineEarnings(){const now=Date.now(),away=clamp((now-(state.last||now))/1000,0,12*3600);if(away<60)return null;const laps=Math.floor(away/lapTime()*.85);if(laps<=0)return null;const earned=laps*cashPerLap(),xp=laps*3,trophies=Math.floor(laps/5);state.cash=Math.min(1e15,state.cash+earned);state.laps+=laps;state.trophies+=trophies;state.totalEarned+=earned;state.last=now;addXp(xp);return {away,laps,earned,xp,trophies}}
function openModal(html,extra=''){const m=$('#modal');if(!m)return;m.innerHTML=`<div class="modal-card ${extra}">${html}</div>`;m.classList.add('show');m.setAttribute('aria-hidden','false');const b=m.querySelector('button');if(b)setTimeout(()=>{try{b.focus()}catch{}},40)}
