function setText(id,val){const el=document.getElementById(id);if(el&&el.textContent!==String(val))el.textContent=val}
function updateHud(){
 setText('cashBalance',cash(state.cash));setText('trophyBalance',fmt(state.trophies));setText('levelValue',fmt(state.level));setText('lapCount',fmt(state.laps));
 setText('statCashLap',cash(cashPerLap()));setText('statPerSec',cash(perSecond())+'/sec');setText('statLap',lapTime().toFixed(1)+'s');setText('statWrench',state.prestige+' 🔧');
 setText('xpValue',fmt(state.xp));setText('xpNeed',fmt(xpNeeded()));
 const xf=document.getElementById('xpFill');if(xf)xf.style.width=clamp(state.xp/xpNeeded()*100,0,100)+'%';
 setText('sidePerSec',cash(perSecond()));setText('sidePerLap',cash(cashPerLap()));setText('countdown',Math.max(0,lapTime()-lapClock).toFixed(1)+'s');
 const lp=document.getElementById('lapProgress');if(lp)lp.style.width=clamp(lapClock/lapTime()*100,0,100)+'%';
 setText('raceNextLap',Math.max(0,lapTime()-lapClock).toFixed(1)+'s');
 const hc=document.getElementById('heroChamp');
 if(state.champ){
