  if(hc)hc.style.display='flex';
  setText('heroChampName','🏁 '+t.name);setText('heroChampLap','LAP '+Math.min(t.laps,Math.floor(c.elapsed/lapTime())+1)+'/'+t.laps);
  const pb=document.getElementById('champPlayerBar'),rb=document.getElementById('champRivalBar');
  if(pb)pb.style.width=clamp(c.elapsed/c.playerTotal*100,0,100)+'%';
