+let lastFrame=performance.now();
+function tick(now){
+ const dt=clamp((now-lastFrame)/1000,0,.25);lastFrame=now;
+ const step=dt*state.speedMult;lapClock+=step;
+ const earn=step*perSecond();state.cash=Math.min(1e15,state.cash+earn);state.totalEarned+=earn;
+ let guard=0;
+ while(lapClock>=lapTime()&&guard<5){
+  const lt=lapTime();lapClock-=lt;state.laps++;const pay=cashPerLap();state.cash=Math.min(1e15,state.cash+pay);state.totalEarned+=pay;addXp(4);
+  if(state.laps%5===0){state.trophies++;showToast('Trophy earned! +1 ✦','gold')}
+  sound('lap');guard++;
+ }
+ if(state.champ)updateChamp(step);
+ saveTimer+=dt;if(saveTimer>=5){save();saveTimer=0}
+ updateHud();
+ try{drawScene(now/1000)}catch(e){if(!drawWarned){drawWarned=true;console.warn('Scene draw failed',e)}}
+ requestAnimationFrame(tick);
+}
+document.addEventListener('click',e=>{
+ const btn=e.target.closest('button');if(!btn)return;
+ if(btn.hasAttribute('data-close-modal')){closeModal();return}
+ const ma=btn.dataset.modalAction;
+ if(ma){closeModal();if(ma==='prestige-confirm')doPrestige();return}
+ if(state.sound)getAudio();
+ const d=btn.dataset;
+ if(d.tab){tab=d.tab;render();sound('tap');return}
+ if(d.speed){state.speedMult=Number(d.speed);save();sound('tap');render();return}
+ if(d.buy){buyMode=Number(d.buy);render();return}
+ if(d.action==='camera'){state.follow=!state.follow;save();sound('tap');render();return}
+ if(d.action==='sound'){state.sound=!state.sound;save();if(state.sound)sound('tap');render();return}
+ if(d.action==='abandon'){if(state.champ){state.champ=null;save();sound('tap');render();showToast('Championship abandoned. Your upgrades are waiting.','info')}return}
+ if(d.action==='prestige'){if(state.unlockedTier<3)return showToast('Unlock Elite Tour before prestiging.','error');showPrestigeConfirm();return}
+ if(d.upgrade){buyUpgrade(d.upgrade);return}
+ if(d.champ!==undefined){startChamp(Number(d.champ));return}
+ if(d.pack!==undefined){openPack(Number(d.pack),d.currency);return}
+ if(d.equip!==undefined){equipCar(Number(d.equip));return}
+ if(d.world!==undefined){selectWorld(Number(d.world));return}
+ if(d.skin){buySkin(d.skin);return}
+});
+const modalEl=$('#modal');if(modalEl)modalEl.addEventListener('click',e=>{if(e.target.id==='modal')closeModal()});
+document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
+document.addEventListener('visibilitychange',()=>{if(document.hidden)save()});
+window.addEventListener('pagehide',save);window.addEventListener('beforeunload',save);
+const offline=offlineEarnings();
+render();
+if(offline){save();setTimeout(()=>showOffline(offline),650)}
+lastFrame=performance.now();
+requestAnimationFrame(tick);
+
 </script>
 </body>
 </html>

